  "arguments": [
    {
      "claim": "The captured member of the Tarsk Highland Volunteers does not qualify as a prisoner of war because the militia fails to meet the ‘fixed distinctive sign’ requirement of Article 4(2)(b) of the Third Geneva Convention.",
      "reasoning": "Article 4(2) limits POW status for members of other militias to those that satisfy four conditions, one of which is ‘that of having a fixed distinctive sign recognizable at a distance’. The militia’s policy of wearing ordinary civilian clothing without insignia means that, at the moment of capture, the individual did not possess such a sign. The requirement is not satisfied by occasional use of a sign; it must be a fixed, recognizable sign. Consequently, the individual is not a combatant entitled to POW status and is instead a civilian who has taken direct part in hostilities, entitled only to the protections of Common Article 3.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "gc_iii",
          "article": "4",
          "quoted_text": "that of having a fixed distinctive sign recognizable at a distance"
        }
      ]
    },
    {
      "claim": "Because the militia member is not a combatant under Article 4(2), he is a civilian who has taken direct part in hostilities and therefore is protected only by Common Article 3, not by POW provisions.",
      "reasoning": "The definition of combatant under the Convention requires compliance with the four conditions of Article 4(2). Failure of any condition, such as the distinctive‑sign requirement, removes combatant status. Civilians who directly participate in hostilities lose protection from attack for the duration of that participation but retain the minimum guarantees of Common Article 3. Thus Ardovia’s refusal to accord POW status is consistent with the treaty framework.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "gc_iii",
          "article": "4",
          "quoted_text": "Members of other militias and members of other volunteer corps, including those of organized resistance movements, belonging to a Party to the conflict and operating in or outside their own territory, even if this territory is occupied, provided that such militias or volunteer corps, including such organized resistance movements, fulfil the following conditions"
        }
      ]
    }
  ]
}

